mapper.select:
SELECT b.COURSE_ID, b.BATCH_ID, c.COURSE_NAME, b.BATCH_NAME, b.CAMPUS_ID, b.START_DATE, b.END_DATE
FROM COURSE_BATCH b JOIN COURSE c ON c.COURSE_ID = b.COURSE_ID
WHERE c.USE_YN = 'Y' AND COALESCE(b.STATUS, '') NOT IN ('DRAFT', '임시등록')
AND c.TRAINING_JOB_CATEGORY_ID = #{trainingJobCategoryId}
AND c.EDUCATION_CATEGORY_ID = #{educationCategoryId}
ORDER BY b.START_DATE DESC, b.COURSE_ID DESC, b.BATCH_ID DESC

SELECT * FROM ADMISSION_APPLICATION WHERE COURSE_ID = #{courseId} AND BATCH_ID = #{batchId}
AND (LOCATE(#{keyword}, APPLICANT_NAME) > 0 OR LOCATE(#{keyword}, PHONE) > 0)
AND APPLICATION_STATUS = #{status}
ORDER BY APPLICATION_ID DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM ADMISSION_APPLICATION WHERE COURSE_ID = #{courseId} AND BATCH_ID = #{batchId} AND
(TRAINEE_ID = #{traineeId} OR (TRIM(APPLICANT_NAME) = #{applicantName} AND BIRTH_DATE = #{birthDate} AND REGEXP_REPLACE(COALESCE(PHONE, ''), '[^0-9]', '') = #{phone}))
AND APPLICATION_ID != #{applicationId}
